bool UnionTraits<::chromeos::network_diagnostics::mojom::RoutineResultValue::DataView, ::chromeos::network_diagnostics::mojom::RoutineResultValuePtr>::Read(
    ::chromeos::network_diagnostics::mojom::RoutineResultValue::DataView input,
    ::chromeos::network_diagnostics::mojom::RoutineResultValuePtr* output) {
  using UnionType = ::chromeos::network_diagnostics::mojom::RoutineResultValue;
  using Tag = UnionType::Tag;

  switch (input.tag()) {
    case Tag::HTTPS_LATENCY_RESULT_VALUE: {
      ::chromeos::network_diagnostics::mojom::HttpsLatencyResultValuePtr result_https_latency_result_value;
      if (!input.ReadHttpsLatencyResultValue(&result_https_latency_result_value))
        return false;

      *output = UnionType::NewHttpsLatencyResultValue(
          std::move(result_https_latency_result_value));
      break;
    }
    default:

      return false;
  }
  return true;
}

